use std::{fs,path::Path};
fn main(){let r="/home/ubuntu/src/zopro-perf-work/g1-control-codegen176";assert!(!Path::new(r).join("compare-helpers.rs").exists());let old=fs::read_to_string(format!("{r}/compare.rs")).unwrap();let mut s=old[..old.find("fn main(){").unwrap()].to_owned();s.push_str(r#"
fn main(){assert!(!Path::new(R).join("helper-comparison.json").exists());let previous:Value=serde_json::from_slice(&fs::read(format!("{R}/comparison.json")).unwrap()).unwrap();let initial:Value=serde_json::from_slice(&fs::read(format!("{R}/analysis.json")).unwrap()).unwrap();let mut rows=BTreeMap::new();let mut raw_rows=BTreeMap::new();
 for label in["original","two_chain_control","descriptor_control"]{
  let binary=initial["rows"][label]["binary"].as_str().unwrap();assert_eq!(h(&fs::read(binary).unwrap()),initial["rows"][label]["binary_sha256"].as_str().unwrap());let nm=fs::read(format!("{R}/{label}/nm.stdout")).unwrap();assert_eq!(h(&nm),initial["rows"][label]["nm"]["stdout_sha256"].as_str().unwrap());let n=String::from_utf8(nm).unwrap();
  for(kind,signature)in[("invert_lanes","zopro_core::msm::invert_lanes"),("inverse_nonzero","<zopro_core::simd::FqBatch>::inverse_nonzero")]{let calls=previous["rows"][label]["external_calls"].as_array().unwrap().iter().filter(|r|r["signature"]==signature).collect::<Vec<_>>();assert!(!calls.is_empty());let addr=calls[0]["target"].as_u64().unwrap();assert!(calls.iter().all(|c|c["target"]==addr));let syms=n.lines().filter_map(|l|{let f=l.split_whitespace().collect::<Vec<_>>();if f.len()!=4{return None}let a=u64::from_str_radix(f[0],16).unwrap();if a==addr{Some((f[3],u64::from_str_radix(f[1],16).unwrap()))}else{None}}).collect::<Vec<_>>();assert_eq!(syms.len(),1);let(raw,size)=syms[0];let path=format!("{label}/{kind}");fs::create_dir(format!("{R}/{path}")).unwrap();let arg=format!("--disassemble={raw}");let argv=["-d","--no-show-raw-insn",&arg,binary];let o=std::process::Command::new("objdump").args(argv).output().unwrap();assert!(o.status.success());fs::write(format!("{R}/{path}/assembly.txt"),&o.stdout).unwrap();fs::write(format!("{R}/{path}/objdump.stderr"),&o.stderr).unwrap();let text=String::from_utf8(o.stdout.clone()).unwrap();let instructions=text.lines().filter(|l|l.trim().split_once(':').is_some_and(|(a,_)|!a.is_empty()&&a.chars().all(|c|c.is_ascii_hexdigit()))).count();let row=json!({"binary":binary,"binary_sha256":initial["rows"][label]["binary_sha256"],"symbol":signature,"address":addr,"bytes":size,"instruction_sites":instructions,"objdump":{"argv":argv,"exit":0,"stdout_sha256":h(&o.stdout),"stderr_sha256":h(&o.stderr)}});rows.insert(path.clone(),normalize(&path,&row));raw_rows.insert(path,row);
  }
 }
 let mut pairs=BTreeMap::new();for kind in["invert_lanes","inverse_nonzero"]{let original=rows[&format!("original/{kind}")]["lines"].as_array().unwrap();for label in["two_chain_control","descriptor_control"]{let other=rows[&format!("{label}/{kind}")]["lines"].as_array().unwrap();let diff=original.iter().zip(other).enumerate().filter(|(_, (a,b))|a!=b).map(|(i,(a,b))|json!({"instruction_index":i,"original":a,"other":b})).collect::<Vec<_>>();pairs.insert(format!("{label}/{kind}"),json!({"original_lines":original.len(),"other_lines":other.len(),"normalized_equal":original==other,"zipped_differences":diff}));}}
 let result=json!({"scope":"one-level hot inversion callee comparison; no new capture or causal claim","rows":rows,"raw_rows":raw_rows,"comparisons":pairs});fs::write(format!("{R}/helper-comparison.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();for(k,c)in result["comparisons"].as_object().unwrap(){println!("{k}: original_rows={} other_rows={} equal={} differing_zipped_rows={}",c["original_lines"],c["other_lines"],c["normalized_equal"],c["zipped_differences"].as_array().unwrap().len());}
}
"#);fs::write(format!("{r}/compare-helpers.rs"),s).unwrap();println!("Prepared bounded one-level hot-callee extraction/comparison with exact same normalizer source");}
